export function getSpeciesSlug(species: Species): string {
  return `${species.genus.toLowerCase()}-${species.speciesEpithet.toLowerCase()}`.replace(/[^a-z0-9-]/g, '');
}

export function getSpeciesBySlug(slug: string): Species | undefined {
  const normalized = slug.toLowerCase().trim();
  return SPECIES_DATA.find(s => getSpeciesSlug(s) === normalized || s.id === normalized);
}
